changeSet.sql:
alter table mandant add constraint mandant_code_laenge_ck check (char_length(code) <= 40);
alter table mandant add constraint mandant_geschaeftsjahr_ende_tag_ck check (
    substr(geschaeftsjahr_ende, 4, 2)::int <= case substr(geschaeftsjahr_ende, 1, 2)
        when '02' then 29 when '04' then 30 when '06' then 30 when '09' then 30 when '11' then 30
        else 31 end);
